import {
  SchemaDocument,
  TypeDefinition,
  TypeNode,
  FieldDefinition,
  EnumValue,
} from '../ir/types';

export interface PythonGeneratorOptions {
  usePydantic?: boolean;
}

/**
 * Generates modern Python (3.10+) models using Pydantic v2 or dataclasses.
 */
export function generatePython(
  doc: SchemaDocument,
  options: PythonGeneratorOptions = { usePydantic: true }
): string {
  const lines: string[] = [
    '# Auto-generated by TypeBridge. DO NOT EDIT DIRECTLY.',
    'from __future__ import annotations',
    'from typing import Optional, List, Dict, Any, Union',
    'from enum import Enum',
    'from datetime import datetime',
    'from uuid import UUID',
  ];

  if (options.usePydantic) {
    lines.push('from pydantic import BaseModel, Field, ConfigDict');
  } else {
    lines.push('from dataclasses import dataclass, field');
  }

  lines.push('');

  for (const def of doc.definitions) {
    if (def.kind === 'struct') {
      lines.push(generateStruct(def, options));
      lines.push('');
    } else if (def.kind === 'enum') {
      lines.push(generateEnum(def));
      lines.push('');
    } else if (def.kind === 'alias') {
      lines.push(`${def.name} = ${mapTypeToPython(def.targetType)}`);
      lines.push('');
    }
  }

  return lines.join('\n');
}

function generateStruct(
  def: Extract<TypeDefinition, { kind: 'struct' }>,
  options: PythonGeneratorOptions
): string {
  const lines: string[] = [];
  if (options.usePydantic) {
    lines.push(`class ${def.name}(BaseModel):`);
    lines.push('    model_config = ConfigDict(populate_by_name=True)');
  } else {
    lines.push('@dataclass');
    lines.push(`class ${def.name}:`);
  }

  if (def.description) {
    lines.push(`    """${def.description}"""`);
  }

  if (def.fields.length === 0) {
    lines.push('    pass');
    return lines.join('\n');
  }

  for (const field of def.fields) {
    const pyName = toSnakeCase(field.name);
    const pyType = mapTypeToPython(field.type);
    const isAliased = pyName !== field.name;

    if (field.description) {
      lines.push(`    # ${field.description}`);
    }

    if (options.usePydantic) {
      if (field.optional) {
        if (isAliased) {
          lines.push(`    ${pyName}: Optional[${pyType}] = Field(default=None, alias="${field.name}")`);
        } else {
          lines.push(`    ${pyName}: Optional[${pyType}] = None`);
        }
      } else {
        if (isAliased) {
          lines.push(`    ${pyName}: ${pyType} = Field(..., alias="${field.name}")`);
        } else {
          lines.push(`    ${pyName}: ${pyType}`);
        }
      }
    } else {
      if (field.optional) {
        lines.push(`    ${pyName}: Optional[${pyType}] = None`);
      } else {
        lines.push(`    ${pyName}: ${pyType}`);
      }
    }
  }

  return lines.join('\n');
}

function generateEnum(def: Extract<TypeDefinition, { kind: 'enum' }>): string {
  const lines: string[] = [`class ${def.name}(str, Enum):`];
  if (def.description) {
    lines.push(`    """${def.description}"""`);
  }

  for (const val of def.values) {
    const safeName = val.name.toUpperCase().replace(/[^A-Z0-9_]/g, '_');
    const safeVal = typeof val.value === 'string' ? `"${val.value}"` : val.value;
    lines.push(`    ${safeName} = ${safeVal}`);
  }

  return lines.join('\n');
}

function mapTypeToPython(node: TypeNode): string {
  switch (node.kind) {
    case 'primitive':
      switch (node.primitive) {
        case 'string':
          return 'str';
        case 'number':
          return 'float';
        case 'integer':
          return 'int';
        case 'boolean':
          return 'bool';
        case 'date':
          return 'datetime';
        case 'uuid':
          return 'UUID';
        case 'null':
          return 'None';
        case 'any':
        default:
          return 'Any';
      }
    case 'reference':
      return node.name;
    case 'array':
      return `List[${mapTypeToPython(node.elementType)}]`;
    case 'map':
      return `Dict[${mapTypeToPython(node.keyType)}, ${mapTypeToPython(node.valueType)}]`;
    case 'optional':
      return `Optional[${mapTypeToPython(node.innerType)}]`;
    case 'union':
      return `Union[${node.types.map(mapTypeToPython).join(', ')}]`;
    case 'literal':
      return typeof node.value === 'string' ? `"${node.value}"` : `${node.value}`;
    default:
      return 'Any';
  }
}

function toSnakeCase(str: string): string {
  return str
    .replace(/([A-Z])/g, '_$1')
    .toLowerCase()
    .replace(/^_/, '');
}
